import{_ as t,o as l,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-03-28 :: Ceph Performance meeting","description":"","frontmatter":{"title":"2019-03-28 :: Ceph Performance meeting","date":"2019-03-28T00:00:00.000Z","updated":"2019-04-10T00:00:00.000Z","tags":["Ceph","RGW性能优化","分布式存储","CRUSH算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-03-28_-_-_Ceph_Performance_meeting.md","filePath":"posts/2019/2019-03-28_-_-_Ceph_Performance_meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-03-28_-_-_Ceph_Performance_meeting.md"};function s(n,e,a,_,p,g){return l(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 未知 <strong>参会人员</strong>： 未知（可能包括Ben、Adam、Casey等人） <strong>会议主题</strong>： Ceph RGW性能优化与相关议题讨论</p><p><strong>会议内容</strong>：</p><ul><li><strong>RGW性能优化</strong>： <ul><li>Ben报告了与Beast和SEO相关的异步工作进展，并提及了对云服务支持的重构。</li><li>讨论了QoS（服务质量）在多站点环境下的应用，特别是bucket动态重启的挑战及其设计方案。</li><li>探讨了CPU资源限制和提升RGW性能的方法，包括减少线程数量以降低内存消耗和上下文切换开销。</li><li>讨论了性能测量方法，如使用wall clock profiler进行性能分析。</li><li>分析了nvme驱动和RBD对性能的影响，以及压缩技术对RGW性能的潜在影响。</li></ul></li><li><strong>其他议题</strong>： <ul><li>提及了默认使用debug Amos zero而不是debug iboga miss one的决策。</li><li>讨论了librettos库中用于禁用blue store压缩的flag。</li></ul></li><li><strong>决定事项</strong>： <ul><li>推进RGW性能优化工作，包括异步重构、QoS优化、减少线程数量等。</li><li>使用wall clock profiler工具进行性能分析。</li><li>默认使用debug Amos zero。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>Ben将继续推进RGW性能优化工作。</li><li>其他参会人员将根据各自职责推进相关工作。</li></ul></li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了Ceph RGW、Beast、SEO、QoS、nvme、RBD、librettos、blue store、debug Amos zero等关键词。</li></ul>',6)])])}const c=t(i,[["render",s]]);export{u as __pageData,c as default};
